        return (l && l.name) || l;
    });
    if (gateLabels.indexOf('pr_approved') === -1) {
        githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, 'ai_validating');
        githubTracker(repoInfo.owner, repoInfo.repo).addLabel(ticket.prNumber, 'ai_validated');
